document.addEventListener("DOMContentLoaded",()=>{const c=document.querySelectorAll(".cat-tag a, .cat-tag button"),n=document.querySelectorAll(".perso");function s(t){if(c.forEach(e=>e.classList.remove("current")),!t||t==="")n.forEach(e=>{e.classList.remove("hidden"),e.classList.add("visible")}),document.querySelector(".cat-tag button.all, .cat-tag a.all")?.classList.add("current");else{n.forEach(a=>{(a.dataset.departments||"").includes(t)?(a.classList.remove("hidden"),a.classList.add("visible")):(a.classList.remove("visible"),a.classList.add("hidden"))});const e=document.querySelector(`.cat-tag a[data-segment="${t}"]`);e&&e.classList.add("current")}}c.forEach(t=>{t.addEventListener("click",e=>{if(e.preventDefault(),t.tagName==="BUTTON")history.pushState(null,"",window.location.pathname+window.location.search),s("");else{const a=t.getAttribute("href").split("#")[1];window.location.hash=a||"",s(a)}})});const o=window.location.hash.replace("#","");s(o),window.addEventListener("hashchange",()=>{const t=window.location.hash.replace("#","");s(t)})});
